[[vk::binding(0, 0)]] RWTexture2D<float4> gOutput;
[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};
[[vk::binding(2, 0)]] RaytracingAccelerationStructure gScene;

struct Payload { float4 c; };

[shader("raygeneration")]
void RayGen()
{
    uint2 idx = DispatchRaysIndex().xy;
    uint2 dim = DispatchRaysDimensions().xy;
    float2 uv = (float2(idx) + 0.5) / float2(dim);
    float2 ndc = uv * 2.0 - 1.0;
    ndc.y = -ndc.y;
    float aspect = float(dim.x) / float(dim.y);
    float3 dir = normalize(float3(ndc.x * aspect, ndc.y, 2.0));

    RayDesc ray;
    ray.Origin = float3(0, 0.5, -3);
    ray.TMin = 0.001;
    ray.Direction = dir;
    ray.TMax = 100.0;

    Payload p;
    p.c = float4(0, 0, 0, 1);
    TraceRay(gScene, RAY_FLAG_NONE, 0xFF, 0, 0, 0, ray, p);
    gOutput[idx] = p.c;
}

struct Payload { float4 c; };
[shader("miss")]
void Miss(inout Payload p)
{
    float3 dir = WorldRayDirection();
    float sky = saturate(0.5 + dir.y);
    p.c = float4(lerp(float3(0.4, 0.6, 0.9), float3(0.05, 0.1, 0.3), sky), 1.0);
}

[shader("intersection")]
void Intersection()
{
    float3 origin = ObjectRayOrigin();
    float3 dir = ObjectRayDirection();
    float3 center = float3(0, 0, 0);
    float radius = 0.5;
    float3 oc = origin - center;
    float a = dot(dir, dir);
    float b = 2.0 * dot(oc, dir);
    float c = dot(oc, oc) - radius * radius;
    float disc = b * b - 4.0 * a * c;
    if (disc >= 0.0) {
        float t = (-b - sqrt(disc)) / (2.0 * a);
        if (t >= RayTMin() && t <= RayTCurrent()) {
            BuiltInTriangleIntersectionAttributes attr;
            float3 hitLocal = origin + dir * t;
            attr.barycentrics = float2(hitLocal.x + 0.5, hitLocal.y + 0.5);
            ReportHit(t, 0, attr);
        }
    }
}

[[vk::binding(1, 0)]] cbuffer Host {
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct Payload { float4 c; };

[shader("closesthit")]
void ClosestHit(inout Payload p, in BuiltInTriangleIntersectionAttributes a)
{
    float t = time_sim_ms * 0.001;
    float3 hitPos = WorldRayOrigin() + WorldRayDirection() * RayTCurrent();
    float3 normal = normalize(hitPos);
    float3 lightDir = normalize(float3(sin(t), 1.0, cos(t)));
    float diff = max(dot(normal, lightDir), 0.0);
    float3 col = float3(0.2, 0.6, 0.9) * (0.2 + 0.8 * diff);
    float spec = pow(max(dot(reflect(-lightDir, normal), -WorldRayDirection()), 0.0), 32.0);
    col += float3(1, 1, 1) * spec * 0.5;
    p.c = float4(col, 1.0);
}
